<template><div class="page-stack"><PageHeader title="Notifications"><button class="btn btn-outline" :disabled="loading" @click="load">Actualiser</button></PageHeader><p v-if="error" class="field-error" role="alert">{{ error }}</p><p v-if="loading" role="status">Chargement…</p><section v-else-if="!error" class="card section-card page-stack"><p v-if="!items.length" class="muted">Aucune notification.</p><article v-for="item in items" :key="item.id" class="notification"><div><h2 class="card-title">{{ item.title }}</h2><p>{{ item.body }}</p><time class="field-hint">{{ item.inserted_at }}</time></div><button v-if="!item.read_at" class="btn btn-outline btn-sm" @click="mark(item)">Marquer comme lue</button><span v-else class="pill pill-ok">Lue</span></article></section></div></template>
<script>
import PageHeader from '../components/ui/PageHeader.vue'
import { listNotifications, readNotification } from '../services/workforceService'
export default { name: 'Notifications', components: { PageHeader }, data() { return { items: [], loading: false, error: '', version: 0 } }, created() { this.load() }, beforeUnmount() { this.version += 1 }, methods: { async load() { const version = ++this.version; this.loading = true; this.error = ''; try { const items = await listNotifications(); if (version === this.version) this.items = items } catch (error) { if (version === this.version) this.error = error.message } finally { if (version === this.version) this.loading = false } }, async mark(item) { try { const saved = await readNotification(item.id); this.items = this.items.map(row => row.id === item.id ? saved : row) } catch (error) { this.error = error.message } } } }
</script>
<style scoped>.notification { display:flex;gap:18px;justify-content:space-between;align-items:center;border-bottom:1px solid var(--border);padding:16px 0; }.notification p { margin:10px 0; }@media(max-width:760px) { .notification { flex-direction:column;align-items:stretch; } }</style>
